.darma-loader-darma-b14-cuckoo-clock { --accent: var(--loader-color, #facc15); --accent-2: var(--loader-secondary-color, #92400e); width: calc(var(--loader-size, 116px) * .82); height: var(--loader-size, 116px); position: relative; overflow: hidden; border-radius: 6% 6% 4px 4px; background: linear-gradient(color-mix(in srgb, #fff 12%, var(--accent-2)), color-mix(in srgb, #000 26%, var(--accent-2))); }
.darma-loader-darma-b14-cuckoo-clock::before { content: ''; position: absolute; top: 0; left: -6%; width: 112%; height: 22%; clip-path: polygon(50% 0, 100% 100%, 0 100%); background: color-mix(in srgb, #000 40%, var(--accent-2)); }
.darma-loader-darma-b14-cuckoo-clock .darma-loader-darma-b14-cuckoo-clock__bird { position: absolute; z-index: 1; top: 30%; left: 42%; width: 17%; height: 16%; border-radius: 50% 34% 50% 40%; background: linear-gradient(var(--accent), color-mix(in srgb, #000 22%, var(--accent))); animation: darma-loader-darma-b14-cuckoo-clock-cuckoo calc(var(--loader-speed, 1s) * 3) ease-in-out infinite; }
.darma-loader-darma-b14-cuckoo-clock span { position: absolute; z-index: 2; top: 26%; width: 21%; height: 24%; background: linear-gradient(color-mix(in srgb, #000 34%, var(--accent-2)), color-mix(in srgb, #000 52%, var(--accent-2))); }
.darma-loader-darma-b14-cuckoo-clock span:nth-child(2) { right: 50%; transform-origin: right center; animation: darma-loader-darma-b14-cuckoo-clock-door-left calc(var(--loader-speed, 1s) * 3) ease-in-out infinite; }
.darma-loader-darma-b14-cuckoo-clock span:nth-child(3) { left: 50%; transform-origin: left center; animation: darma-loader-darma-b14-cuckoo-clock-door-right calc(var(--loader-speed, 1s) * 3) ease-in-out infinite; }
.darma-loader-darma-b14-cuckoo-clock .darma-loader-darma-b14-cuckoo-clock__pendulum { position: absolute; top: 58%; left: 48%; width: 3.5%; height: 30%; transform-origin: top center; background: #cbd5e1; animation: darma-loader-darma-b14-cuckoo-clock-tick-tock calc(var(--loader-speed, 1s) * 1.5) ease-in-out infinite; }
.darma-loader-darma-b14-cuckoo-clock .darma-loader-darma-b14-cuckoo-clock__pendulum::after { content: ''; position: absolute; top: 98%; left: -190%; width: 480%; height: 22%; border-radius: 50%; background: var(--accent); }
@keyframes darma-loader-darma-b14-cuckoo-clock-door-left { 0%, 28% { transform: perspective(200px) rotateY(0deg); } 44%, 68% { transform: perspective(200px) rotateY(-80deg); } 84%, 100% { transform: perspective(200px) rotateY(0deg); } }
@keyframes darma-loader-darma-b14-cuckoo-clock-door-right { 0%, 28% { transform: perspective(200px) rotateY(0deg); } 44%, 68% { transform: perspective(200px) rotateY(80deg); } 84%, 100% { transform: perspective(200px) rotateY(0deg); } }
@keyframes darma-loader-darma-b14-cuckoo-clock-cuckoo { 0%, 32% { opacity: 0; transform: translateX(0); } 40% { opacity: 1; } 52%, 64% { opacity: 1; transform: translateX(-56%); } 80%, 100% { opacity: 0; transform: translateX(0); } }
@keyframes darma-loader-darma-b14-cuckoo-clock-tick-tock { 0%, 100% { transform: rotate(-15deg); } 50% { transform: rotate(15deg); } }

